package adminstudio

import (
	"errors"
	"html/template"
	"io"
)

var ErrInvalidForm = errors.New("invalid admin form")

type FormData struct {
	Collection  Collection
	Action      string
	CSRFToken   string
	Values      map[string]string
	SubmitLabel string
	HideSubmit  bool
	Nonce       string
}

var createFormTemplate = template.Must(template.New("admin-create-form").Parse(`{{range .Collection.Fields}}{{$field := .}}{{if and (ne .Kind "relation") (not .ReadOnly)}}{{if eq .Widget "hidden"}}<input type="hidden" name="{{.ID}}" value="{{index $.Values .ID}}">{{else}}{{if eq .Widget "media"}}<div class="media-select-field"><label>{{.Label}}{{if .Required}} *{{end}}<input id="media_{{.ID}}" name="{{.ID}}" value="{{index $.Values .ID}}" placeholder="Medyadan seçin"{{if .Required}} required{{end}}></label><button class="button button-quiet media-picker-open" type="button" data-media-target="media_{{.ID}}">Kütüphaneden seç</button></div>{{else if or (eq .Widget "richtext") (eq .ID "body") (eq .ID "description")}}<div class="studio-form-field full-width richtext-wrap"><span class="studio-form-label">{{.Label}}{{if .Required}} *{{end}}</span><div class="richtext-field" data-richtext><div class="richtext-toolbar ql-toolbar ql-snow"><button type="button" class="ql-bold" aria-label="Kalın"></button><button type="button" class="ql-italic" aria-label="İtalik"></button><button type="button" class="ql-underline" aria-label="Altı çizili"></button><button type="button" class="ql-link" aria-label="Bağlantı"></button><button type="button" class="ql-list" value="ordered" aria-label="Numaralı liste"></button><button type="button" class="ql-list" value="bullet" aria-label="Madde listesi"></button><button type="button" class="ql-blockquote" aria-label="Alıntı"></button></div><div class="richtext-editor ql-container ql-snow"></div><textarea class="richtext-value" name="{{.ID}}" hidden>{{index $.Values .ID}}</textarea></div></div>{{else}}<label>{{.Label}}{{if .Required}} *{{end}}{{if or (eq .Kind "status") (gt (len .Options) 0)}}<select name="{{.ID}}"{{if .Required}} required{{end}}>{{range .Options}}<option value="{{.}}"{{if eq (index $.Values $field.ID) .}} selected{{end}}>{{.}}</option>{{end}}</select>{{else if eq .Widget "textarea"}}<textarea name="{{.ID}}"{{if .Required}} required{{end}}>{{index $.Values .ID}}</textarea>{{else}}<input name="{{.ID}}" type="{{if eq .Kind "number"}}number{{else}}text{{end}}" value="{{index $.Values .ID}}"{{if .Required}} required{{end}}>{{end}}</label>{{end}}{{end}}{{end}}{{end}}<input type="hidden" name="_csrf" value="{{.CSRFToken}}">{{if not .HideSubmit}}<button type="submit">{{if .SubmitLabel}}{{.SubmitLabel}}{{else}}Create{{end}}</button>{{end}}{{if .Nonce}}<div id="admin-media-picker-modal" class="admin-media-picker-modal" hidden><div class="admin-media-picker-dialog" role="dialog" aria-modal="true" aria-label="Medya kütüphanesi"><div><p class="eyebrow">MEDYA KÜTÜPHANESİ</p><h2>Görsel seç</h2></div><button class="button button-quiet" type="button" data-media-close>Kapat</button><p>Yalnız hazır görseller listelenir. Yeni görseli Medya alanından yükleyin.</p><div id="admin-media-picker-grid" class="admin-media-picker-grid"></div></div></div><style nonce="{{.Nonce}}">.media-select-field{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:end}.media-select-field label{min-width:0}.media-select-field .button{padding:10px 12px;white-space:nowrap}.admin-media-picker-modal{position:fixed;inset:0;z-index:200;display:grid;place-items:center;padding:24px;background:rgba(15,23,42,.45);backdrop-filter:blur(4px)}.admin-media-picker-modal[hidden]{display:none}.admin-media-picker-dialog{width:min(860px,100%);max-height:min(78vh,760px);overflow:auto;padding:24px;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius-xl);box-shadow:var(--shadow-lg)}.admin-media-picker-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px;margin-top:18px}.admin-media-picker-item{display:grid;gap:7px;padding:8px;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--bg-subtle);color:var(--ink);text-align:left;font:inherit;cursor:pointer}.admin-media-picker-item:hover{border-color:var(--brand);background:var(--brand-subtle)}.admin-media-picker-item img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:6px;background:var(--surface-hover)}.admin-media-picker-item small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}@media(max-width:620px){.media-select-field{grid-template-columns:1fr}.media-select-field .button{width:100%}}</style><script nonce="{{.Nonce}}">(function(){if(window.HydroInitQuill)window.HydroInitQuill();var modal=document.getElementById('admin-media-picker-modal'),grid=document.getElementById('admin-media-picker-grid'),target=null;if(!modal||!grid)return;function close(){modal.hidden=true;target=null}document.addEventListener('click',async function(event){var opener=event.target.closest('.media-picker-open');if(opener){target=document.getElementById(opener.dataset.mediaTarget);if(!target)return;modal.hidden=false;grid.textContent='Görseller yükleniyor…';try{var response=await fetch('/api/media',{headers:{Accept:'application/json'}}),assets=await response.json();if(!response.ok)throw new Error('library unavailable');grid.innerHTML='';assets.filter(function(asset){return asset.status==='ready'&&asset.mime_type.indexOf('image/')===0}).forEach(function(asset){var button=document.createElement('button'),image=document.createElement('img'),name=document.createElement('small');button.type='button';button.className='admin-media-picker-item';button.dataset.assetId=asset.id;image.src='/media/'+encodeURIComponent(asset.id);image.alt=asset.original_filename;name.textContent=asset.original_filename;button.append(image,name);grid.append(button)});if(!grid.childElementCount)grid.textContent='Seçilebilecek hazır görsel yok.'}catch(_){grid.textContent='Medya kütüphanesi açılamadı.'}}if(event.target.closest('[data-media-close]'))close();var choice=event.target.closest('.admin-media-picker-item');if(choice&&target){target.value=choice.dataset.assetId;target.dispatchEvent(new Event('input',{bubbles:true}));close()}})})();</script>{{end}}`))

// RenderCreateForm renders metadata-driven controls only. The surrounding
// module handler remains responsible for authorization, validation, service
// invocation, audit, and response navigation.
func RenderCreateForm(w io.Writer, data FormData) error {
	if _, err := NewRegistry([]Collection{data.Collection}); err != nil || data.Action == "" || data.Action[0] != '/' || (len(data.Action) > 1 && data.Action[1] == '/') || data.CSRFToken == "" {
		return ErrInvalidForm
	}
	if data.Values == nil {
		data.Values = map[string]string{}
	}
	return createFormTemplate.Execute(w, data)
}
